1	/* Set TikTok ads dashboard date range. Sync IIFE for ziniao page exec.
2	 * Placeholders replaced by PowerShell: __DATE_MODE__ (yesterday|today), __ACTION__ (open|pick|status)
3	 * No // comments (minified to one line). */
4	(function () {
5	  var MODE = '__DATE_MODE__';
6	  var ACTION = '__ACTION__';
7	
8	  function cleanText(t) {
9	    return String(t == null ? '' : t)
10	      .replace(/\s+/g, ' ')
11	      .trim();
12	  }
13	
14	  function pad2(n) {
15	    return (n < 10 ? '0' : '') + n;
16	  }
17	
18	  function formatYmd(d) {
19	    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
20	  }
21	
22	  function targetMeta(mode) {
23	    var today = new Date();
24	    today.setHours(0, 0, 0, 0);
25	    var y = new Date(today.getTime());
26	    y.setDate(y.getDate() - 1);
27	    if (mode === 'today') {
28	      return { start: formatYmd(today), end: formatYmd(today), labels: ['今天', '今日', 'Today', 'today'] };
29	    }
30	    return {
31	      start: formatYmd(y),
32	      end: formatYmd(y),
33	      labels: ['昨天', '昨日', 'Yesterday', 'yesterday']
34	    };
35	  }
36	
37	  function parseRangeFromText(text) {
38	    var t = cleanText(text);
39	    var m = t.match(/(\d{4}[-\/]\d{1,2}[-\/]\d{1,2})\s*[-–~至到]\s*(\d{4}[-\/]\d{1,2}[-\/]\d{1,2})/);
40	    if (!m) return null;
41	    function norm(s) {
42	      var p = s.replace(/\//g, '-').split('-');
43	      return p[0] + '-' + pad2(Number(p[1])) + '-' + pad2(Number(p[2]));
44	    }
45	    return { start: norm(m[1]), end: norm(m[2]), raw: m[0] };
46	  }
47	
48	  function isVisible(el) {
49	    if (!el || el.nodeType !== 1) return false;
50	    var st = window.getComputedStyle(el);
51	    if (!st || st.display === 'none' || st.visibility === 'hidden' || Number(st.opacity) === 0) {
52	      return false;
53	    }
54	    var r = el.getBoundingClientRect();
55	    return r.width > 0 && r.height > 0;
56	  }
57	
58	  function clickEl(el) {
59	    if (!el) return false;
60	    try {
61	      el.scrollIntoView({ block: 'center', inline: 'center' });
62	    } catch (e) {}
63	    try {
64	      if (el.focus) el.focus();
65	    } catch (e2) {}
66	    var opts = { bubbles: true, cancelable: true, view: window };
67	    try {
68	      el.dispatchEvent(new MouseEvent('mousedown', opts));
69	      el.dispatchEvent(new MouseEvent('mouseup', opts));
70	      el.dispatchEvent(new MouseEvent('click', opts));
71	    } catch (e3) {
72	      try {
73	        el.click();
74	      } catch (e4) {
75	        return false;
76	      }
77	    }
78	    return true;
79	  }
80	
81	  function readDisplayedRange() {
82	    var nodes = document.querySelectorAll('input, button, div, span, p, a');
83	    var best = null;
84	    for (var i = 0; i < nodes.length && i < 5000; i++) {
85	      var el = nodes[i];
86	      if (!isVisible(el)) continue;
87	      var text = '';
88	      if (el.tagName === 'INPUT') text = el.value || el.getAttribute('placeholder') || '';
89	      else text = el.innerText || el.textContent || '';
90	      text = cleanText(text).slice(0, 80);
91	      var rg = parseRangeFromText(text);
92	      if (!rg) continue;
93	      var r = el.getBoundingClientRect();
94	      if (r.top > window.innerHeight * 0.55) continue;
95	      best = { el: el, range: rg, text: text };
96	      if (el.tagName === 'INPUT' || /picker|date|calendar|range/i.test(el.className || '')) break;
97	    }
98	    return best;
99	  }
100	
101	  function findDateTrigger() {
102	    var shown = readDisplayedRange();
103	    if (shown && shown.el) {
104	      var cur = shown.el;
105	      for (var d = 0; d < 6 && cur; d++) {
106	        if (
107	          cur.matches &&
108	          cur.matches(
109	            'button, [role="button"], input, .arco-picker, .arco-picker-range, [class*="picker"], [class*="Picker"], [class*="date"], [class*="Date"]'
110	          )
111	        ) {
112	          return { el: cur, range: shown.range, via: 'range-text' };
113	        }
114	        cur = cur.parentElement;
115	      }
116	      return { el: shown.el, range: shown.range, via: 'range-text' };
117	    }
118	    var sels = [
119	      '.arco-picker-range',
120	      '.arco-picker',
121	      '[class*="RangePicker"]',
122	      '[class*="range-picker"]',
123	      '[class*="DatePicker"]',
124	      'input[placeholder*="日期"]',
125	      'input[placeholder*="Date"]'
126	    ];
127	    for (var s = 0; s < sels.length; s++) {
128	      var list = document.querySelectorAll(sels[s]);
129	      for (var j = 0; j < list.length; j++) {
130	        if (isVisible(list[j])) return { el: list[j], range: null, via: sels[s] };
131	      }
132	    }
133	    return null;
134	  }
135	
136	  function findShortcut(labels) {
137	    var nodes = document.querySelectorAll(
138	      'button, a, li, div, span, [role="button"], [role="option"], [role="menuitem"]'
139	    );
140	    var candidates = [];
141	    for (var i = 0; i < nodes.length && i < 8000; i++) {
142	      var el = nodes[i];
143	      if (!isVisible(el)) continue;
144	      var t = cleanText(el.innerText || el.textContent || '');
145	      if (!t || t.length > 20) continue;
146	      for (var k = 0; k < labels.length; k++) {
147	        if (t === labels[k] || t.toLowerCase() === String(labels[k]).toLowerCase()) {
148	          candidates.push({ el: el, text: t, exact: true });
149	          break;
150	        }
151	      }
152	    }
153	    if (!candidates.length) {
154	      for (var i2 = 0; i2 < nodes.length && i2 < 8000; i2++) {
155	        var el2 = nodes[i2];
156	        if (!isVisible(el2)) continue;
157	        var t2 = cleanText(el2.innerText || el2.textContent || '');
158	        if (!t2 || t2.length > 20) continue;
159	        for (var k2 = 0; k2 < labels.length; k2++) {
160	          var lab = String(labels[k2]);
161	          if (t2.indexOf(lab) >= 0 || t2.toLowerCase().indexOf(lab.toLowerCase()) >= 0) {
162	            candidates.push({ el: el2, text: t2, exact: false });
163	            break;
164	          }
165	        }
166	      }
167	    }
168	    if (!candidates.length) return null;
169	    candidates.sort(function (a, b) {
170	      return (b.exact ? 1 : 0) - (a.exact ? 1 : 0) || a.text.length - b.text.length;
171	    });
172	    return candidates[0];
173	  }
174	
175	  function panelOpen() {
176	    var panelSels = [
177	      '.arco-picker-container',
178	      '.arco-trigger-popup',
179	      '.arco-panel-date',
180	      '[class*="picker-container"]',
181	      '[class*="PickerDropdown"]',
182	      '[class*="datepicker"]',
183	      '[class*="DatePicker"]',
184	      '[class*="calendar-panel"]',
185	      '[class*="shortcut"]'
186	    ];
187	    for (var i = 0; i < panelSels.length; i++) {
188	      var els = document.querySelectorAll(panelSels[i]);
189	      for (var j = 0; j < els.length; j++) {
190	        if (isVisible(els[j])) return true;
191	      }
192	    }
193	    return !!findShortcut(['今天', '昨天', '近7天', 'Today', 'Yesterday', 'Last 7 days']);
194	  }
195	
196	  var mode = String(MODE || 'yesterday').toLowerCase();
197	  if (mode !== 'today' && mode !== 'yesterday') mode = 'yesterday';
198	  var action = String(ACTION || 'status').toLowerCase();
199	  var target = targetMeta(mode);
200	  var shown = readDisplayedRange();
201	  var range = shown ? shown.range : null;
202	
203	  if (action === 'status') {
204	    var matchedStatus =
205	      !!(range && range.start === target.start && range.end === target.end);
206	    return JSON.stringify({
207	      ok: true,
208	      action: 'status',
209	      mode: mode,
210	      range: range,
211	      target: { start: target.start, end: target.end },
212	      matched: matchedStatus,
213	      panelOpen: panelOpen()
214	    });
215	  }
216	
217	  if (
218	    range &&
219	    range.start === target.start &&
220	    range.end === target.end &&
221	    action !== 'pick'
222	  ) {
223	    return JSON.stringify({
224	      ok: true,
225	      skipped: true,
226	      action: action,
227	      mode: mode,
228	      before: range,
229	      after: range,
230	      message: 'already on target range'
231	    });
232	  }
233	
234	  if (action === 'open') {
235	    var trigger = findDateTrigger();
236	    if (!trigger || !trigger.el) {
237	      return JSON.stringify({
238	        ok: false,
239	        action: 'open',
240	        mode: mode,
241	        before: range,
242	        error: '未找到日期选择器（页面上无日期区间控件）'
243	      });
244	    }
245	    clickEl(trigger.el);
246	    if (!panelOpen() && trigger.el.parentElement) {
247	      clickEl(trigger.el.parentElement);
248	    }
249	    if (!panelOpen()) {
250	      var icon =
251	        document.querySelector('[class*="calendar"]') ||
252	        document.querySelector('[class*="Calendar"]');
253	      if (icon) {
254	        clickEl(icon.closest ? icon.closest('button, div, span') || icon : icon);
255	      }
256	    }
257	    return JSON.stringify({
258	      ok: true,
259	      action: 'open',
260	      mode: mode,
261	      before: range,
262	      triggerVia: trigger.via,
263	      panelOpen: panelOpen(),
264	      message: 'date picker open clicked'
265	    });
266	  }
267	
268	  if (action === 'pick') {
269	    if (!panelOpen()) {
270	      var trigger2 = findDateTrigger();
271	      if (trigger2 && trigger2.el) clickEl(trigger2.el);
272	    }
273	    var sc = findShortcut(target.labels);
274	    if (!sc) {
275	      return JSON.stringify({
276	        ok: false,
277	        action: 'pick',
278	        mode: mode,
279	        before: range,
280	        panelOpen: panelOpen(),
281	        error: '未找到快捷项: ' + target.labels.join('/')
282	      });
283	    }
