199	function Maximize-ZiniaoBrowserWindows {
200	  # 紫鸟开店默认常是小窗；Win32 最大化有助于广告表完整渲染
201	  $code = @'
202	using System;
203	using System.Text;
204	using System.Collections.Generic;
205	using System.Runtime.InteropServices;
206	
207	public class ZiniaoWinMax {
208	  public delegate bool EnumProc(IntPtr hWnd, IntPtr lParam);
209	  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc lpEnumFunc, IntPtr lParam);
210	  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
211	  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
212	  [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
213	  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
214	  const int SW_MAXIMIZE = 3;
215	
216	  public static int MaximizeMatching() {
217	    int n = 0;
218	    EnumWindows((hWnd, l) => {
219	      if (!IsWindowVisible(hWnd)) return true;
220	      var title = new StringBuilder(512);
221	      var cls = new StringBuilder(256);
222	      GetWindowText(hWnd, title, title.Capacity);
223	      GetClassName(hWnd, cls, cls.Capacity);
224	      string t = title.ToString();
225	      string c = cls.ToString();
226	      // 紫鸟店铺窗多为 Chromium；标题常含 TikTok / seller / 店铺名
227	      bool chrome = c.IndexOf("Chrome_WidgetWin", StringComparison.OrdinalIgnoreCase) >= 0
228	                 || c.IndexOf("Chrome_WidgetWin_1", StringComparison.OrdinalIgnoreCase) >= 0;
229	      bool hint = t.IndexOf("TikTok", StringComparison.OrdinalIgnoreCase) >= 0
230	               || t.IndexOf("tiktok", StringComparison.OrdinalIgnoreCase) >= 0
231	               || t.IndexOf("seller", StringComparison.OrdinalIgnoreCase) >= 0
232	               || t.IndexOf("紫鸟", StringComparison.OrdinalIgnoreCase) >= 0
233	               || t.IndexOf("Ziniao", StringComparison.OrdinalIgnoreCase) >= 0
234	               || t.IndexOf("ads-creation", StringComparison.OrdinalIgnoreCase) >= 0;
235	      if (chrome && (hint || t.Length > 0)) {
236	        // 避免把用户普通 Chrome 主页误最大化：要求标题像店铺/广告或非空且 chrome
237	        if (hint || t.IndexOf("Shop", StringComparison.OrdinalIgnoreCase) >= 0) {
238	          ShowWindow(hWnd, SW_MAXIMIZE);
239	          n++;
240	        }
241	      }
242	      return true;
243	    }, IntPtr.Zero);
244	    return n;
245	  }
246	}
247	'@
248	  if (-not ('ZiniaoWinMax' -as [type])) {
249	    Add-Type -TypeDefinition $code -ErrorAction Stop
250	  }
251	  return [ZiniaoWinMax]::MaximizeMatching()
252	}
