25	export function toBitableFields(row, resolvedMap) {
26	  const dateMs = row.date ? new Date(`${row.date}T00:00:00`).getTime() : Date.now();
27	  const scrapedMs = row.scrapedAt ? new Date(row.scrapedAt).getTime() : Date.now();
28	
29	  const planLabel =
30	    row.planStatus === 'on'
31	      ? '投放中'
32	      : row.planStatus === 'off'
33	        ? '已关闭'
34	        : row.planStatus
35	          ? row.planStatus === 'unknown'
36	            ? '未知'
37	            : String(row.planStatus)
38	          : '';
39	
40	  const logical = {
41	    date: dateMs,
42	    store: row.store || '',
43	    storeId: row.storeId || '',
44	    campaign: row.campaign || '',
45	    spend: Number(row.spend) || 0,
46	    orders: Number(row.orders) || 0,
47	    roi: Number(row.roi) || 0,
48	    revenue: Number(row.revenue) || 0,
49	    scrapedAt: scrapedMs,
50	    sourceUrl: row.sourceUrl || '',
51	    status: row.status || 'success',
52	    planStatus: planLabel
53	  };
54	
55	  // 无映射时用默认中文名（兼容旧逻辑）
56	  if (!resolvedMap) {
57	    const out = {};
58	    for (const [k, v] of Object.entries(logical)) {
59	      const name = BITABLE_FIELDS[k];
60	      if (name) out[name] = v;
61	    }
