74	/**
75	 * @param {unknown} value
76	 * @param {number} type 飞书字段 type
77	 */
78	function coerceValue(value, type) {
79	  // 1 text, 3 single select, 4 multi, 15 url → string
80	  // 2 number → number
81	  // 5 datetime → ms
82	  if (type === 2) {
83	    const n = Number(value);
84	    return Number.isFinite(n) ? n : 0;
85	  }
86	  if (type === 5) {
87	    if (typeof value === 'number') return value;
88	    const t = new Date(value).getTime();
89	    return Number.isFinite(t) ? t : Date.now();
90	  }
91	  if (type === 3) {
92	    // 单选：传选项名字符串
93	    return String(value ?? '');
94	  }
