async function setPageDateRange(mode = 'yesterday') {
  let m = String(mode || 'yesterday').toLowerCase();
  if (m !== 'today' && m !== 'yesterday') m = 'yesterday';
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const y = new Date(today.getTime());
  y.setDate(y.getDate() - 1);
  const target =
    m === 'today'
      ? { start: formatYmd(today), end: formatYmd(today), labels: ['今天', '今日', 'Today', 'today'] }
      : {
          start: formatYmd(y),
          end: formatYmd(y),
          labels: ['昨天', '昨日', 'Yesterday', 'yesterday']
        };

  const before = readDisplayedRange();
  const beforeRange = before?.range || null;
  if (
    beforeRange &&
    beforeRange.start === target.start &&
    beforeRange.end === target.end
  ) {
    return {
      ok: true,
      skipped: true,
      mode: m,
      before: beforeRange,
      after: beforeRange,
      message: 'already on target range'
    };
  }

  const trigger = findDateTrigger();
  if (!trigger?.el) {
    return {
      ok: false,
      mode: m,
      before: beforeRange,
      error: '未找到日期选择器'
    };
