  # custom 仅影响业务日期标签；页面区间仍切到昨天，避免抓近 7 天
  Write-Step ("dateMode={0} is not today/yesterday; page date range will use yesterday" -f $dateMode)
  $dateMode = 'yesterday'
}
$currencyCfg = Get-CurrencyConfig $cfg
$scrapeRetries = 2
$scrapeRetryWaitMs = 12000
$waitAfterDateChangeMs = 8000
$setPageDateRange = $true
if ($null -ne $cfg.options.scrapeRetries) { $scrapeRetries = [int]$cfg.options.scrapeRetries }
