  if (String(dateMode).toLowerCase() === 'today') {
    try {
      const ukHour = Number(
        new Intl.DateTimeFormat('en-GB', {
          timeZone: bizTimeZone,
          hour: 'numeric',
          hour12: false
        }).format(new Date())
