        );
        dateMode = 'yesterday';
      }
    } catch (e) {
      console.warn('[TK-Ad] UK hour check failed', e);
    }
  }

  if (setDate) {
    try {
      dateRangeMeta = await setPageDateRange(dateMode, { bizTimeZone });
      if (dateRangeMeta?.ok && !dateRangeMeta.skipped) {
