  try {
    if (!chrome.notifications?.create) return;
    await chrome.notifications.create({
      type: 'basic',
      iconUrl: 'icons/icon128.png',
      title,
      message: String(message).slice(0, 200)
    });
  } catch {
    /* 部分环境无 notifications 权限也可忽略 */
  }
}

